function normText(v){
  let s=v==null?'':String(v);try{s=s.normalize('NFKC');}catch(e){}
  return s.toLowerCase().replace(/ё/g,'е').replace(/[‐‑‒–—−]/g,'-').replace(/[^\p{L}\p{N}+-]+/gu,' ').replace(/\s+/g,' ').trim();
}
function searchNormText(v){
  let s=v==null?'':String(v);try{s=s.normalize('NFKC');}catch(e){}
  return s.toLowerCase().replace(/ё/g,'е').replace(/[\p{Pd}−]+/gu,' ').replace(/[^\p{L}\p{N}]+/gu,' ').replace(/\s+/g,' ').trim();
}
function escapeRe(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function removePhrase(text,phrase){
  if(!text||!phrase)return text;
  return text.replace(new RegExp('(?:^|\\s)'+escapeRe(phrase).replace(/\\ /g,'\\s+')+'(?=\\s|$)','gu'),' ').replace(/\s+/g,' ').trim();
}
function fnv1a32(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0;}return('00000000'+h.toString(16)).slice(-8);}
function baseStem(token){
  let x=normText(token).replace(/[^\p{L}\p{N}-]/gu,'');
  const endings=['иями','ями','ами','ого','ему','ому','ыми','ими','овать','ировать','ение','ения','ений','ировать','овать','ать','ять','ить','еть','уть','ой','ей','ая','яя','ое','ее','ые','ие','ий','ый','ого','ему','ому','ов','ев','ам','ям','ах','ях','ом','ем','а','я','ы','и','у','ю','е','ь'];
  for(const z of endings){if(x.endsWith(z)&&x.length-z.length>=3){x=x.slice(0,-z.length);break;}}
  return x;
}
function regionStem(token){
  let x=normText(token).replace(/[^\p{L}\p{N}-]/gu,'');
  if(x==='г'||x==='город')return'';
  const adminRoots=['област','кра','край','республик','округ','район','автоном'];
  const endings=['иями','ями','ами','ского','ской','скому','скими','ских','ская','ское','ский','цкий','цкая','цкое','ого','ему','ому','ыми','ими','ой','ей','ая','яя','ое','ее','ые','ие','ий','ый','ов','ев','ам','ям','ах','ях','ом','ем','а','я','ы','и','у','ю','е','ь'];
  for(const z of endings){if(x.endsWith(z)&&x.length-z.length>=2){x=x.slice(0,-z.length);break;}}
  if(adminRoots.includes(x))return'';
  return x;
}
function actionOntology(){
  return [
    ['INSTALL',/(?:^|\s)(?:монтаж\p{L}*|смонтир\p{L}*|установ\p{L}*|пусконалад\p{L}*|устройств(?:о|а|у|ом|е))(?=\s|$)/giu],
    ['DESIGN',/(?:^|\s)(?:проектир\p{L}*|разработк\p{L}*\s+(?:проект\p{L}*|рабоч\p{L}*\s+документац\p{L}*)|проектн\p{L}*\s+документац\p{L}*|рабоч\p{L}*\s+документац\p{L}*)(?=\s|$)/giu],
    ['REPAIR',/(?:^|\s)(?:капитальн\p{L}*\s+ремонт\p{L}*|ремонт\p{L}*|восстанов\p{L}*)(?=\s|$)/giu],
    ['RECONSTRUCTION',/(?:^|\s)(?:реконструк\p{L}*|модернизац\p{L}*|замен\p{L}*)(?=\s|$)/giu],
    ['MAINTENANCE',/(?:^|\s)(?:техническ\p{L}*\s+обслужив\p{L}*|обслужив\p{L}*|сервисн\p{L}*\s+обслужив\p{L}*|сервис\p{L}*)(?=\s|$)/giu],
    ['SUPPLY',/(?:^|\s)(?:поставк\p{L}*|поставить|закупк\p{L}*\s+(?:товар\p{L}*|оборудован\p{L}*|материал\p{L}*)|приобретен\p{L}*)(?=\s|$)/giu],
    ['INSPECTION',/(?:^|\s)(?:обследован\p{L}*|диагностик\p{L}*|испытан\p{L}*|техническ\p{L}*\s+приемк\p{L}*|техническ\p{L}*\s+приёмк\p{L}*)(?=\s|$)/giu],
    ['DISMANTLE',/(?:^|\s)(?:демонтаж\p{L}*|демонтир\p{L}*)(?=\s|$)/giu],
    ['CONSTRUCTION',/(?:^|\s)(?:строительств\p{L}*)(?=\s|$)/giu]
