}
function deriveServiceContract(service){
  const normalized=normText(service),actions=[],spans=[];
  let stripped=' '+normalized+' ';
  for(const [cls,rx0] of actionOntology()){
    const rx=new RegExp(rx0.source,rx0.flags);let m;
    while((m=rx.exec(' '+normalized+' '))){actions.push(cls);spans.push({cls,index:m.index,text:m[0].trim()});if(m[0].length===0)rx.lastIndex++;}
    stripped=stripped.replace(new RegExp(rx0.source,rx0.flags),' ');
  }
  const actionClasses=[...new Set(actions)];
  let actionMode=actionClasses.length>1?'ANY':'ANY';
  if(actionClasses.length>1){
    const ordered=spans.slice().sort((a,b)=>a.index-b.index);
    const first=ordered[0],last=ordered[ordered.length-1];
    const between=(' '+normalized+' ').slice(first.index+first.text.length,last.index+last.text.length+2);
    if(/(?:^|\s)(?:и|а\s+также|плюс|\+)(?:\s|$)/u.test(between)&&!/(?:^|\s)(?:или|либо)(?:\s|$)|\//u.test(between))actionMode='ALL';
  }
