  for(const t of rawTerms){const st=baseStem(t);if(!st||seen.has(st))continue;seen.add(st);terms.push(t);stems.push(st);}
  const qualifiers=terms.length>1?terms.slice(0,-1):[];
  return {service_contract_version:'tender-service-v3',governing_action_relation_version:'tender-action-object-binding-v2',normalized_service:normalized,requested_action_classes:actionClasses.length?actionClasses:['UNSPECIFIED'],requested_action_mode:actionMode,requested_object_text:stripped,requested_object_terms:terms,requested_object_stems:stems,requested_qualifiers:qualifiers};
}
function deriveRegionContract(region,scope){
  const normalized=normText(region),terms=[],seen=new Set();
  for(const tok of normalized.split(/[\s-]+/u).filter(Boolean)){const st=regionStem(tok);if(st&&!seen.has(st)){seen.add(st);terms.push(st);}}
