      else if(authority.indexOf(':')>=0)return null;
    }
    host=host.toLowerCase().replace(/\.$/,'').replace(/^www\./,'');
    if(!host||!/^([a-z0-9\u00a1-\uffff-]+\.)*[a-z0-9\u00a1-\uffff-]+$/i.test(host))return null;
    let path=m[3]||'/';
    if(!path.startsWith('/'))path='/'+path;
    const rawQuery=m[4]||'';
    const pairs=[];
    const params={};
    if(rawQuery){
      for(const part of rawQuery.split('&')){
        if(part==='')continue;
        const eq=part.indexOf('=');
        const rk=eq>=0?part.slice(0,eq):part;
        const rv=eq>=0?part.slice(eq+1):'';
        let dk=rk,dv=rv;
        try{dk=decodeURIComponent(rk.replace(/\+/g,' '));}catch(e){}
        try{dv=decodeURIComponent(rv.replace(/\+/g,' '));}catch(e){}
        const lk=String(dk).toLowerCase();
        if(/^utm_(source|medium|campaign|term|content)$/.test(lk)||['gclid','yclid','fbclid','_openstat'].includes(lk))continue;
        pairs.push(eq>=0?(rk+'='+rv):rk);
        if(params[dk]===undefined)params[dk]=dv;
      }
    }
    if(path.length>1&&path.endsWith('/'))path=path.slice(0,-1);
    const query=pairs.join('&');
    return {scheme,host,port,path,query,params,normalized:scheme+'://'+host+(port?(':'+port):'')+path+(query?('?'+query):'')};
  }
