      if(u.protocol!=='http:'&&u.protocol!=='https:')return manual();
      let host=String(u.hostname||'').toLowerCase().replace(/\.$/,'').replace(/^www\./,'');
      if(!host)return manual();
      const pairs=[];const params={};
      for(const [k,v] of u.searchParams.entries()){
        const lk=String(k).toLowerCase();
        if(/^utm_(source|medium|campaign|term|content)$/.test(lk)||['gclid','yclid','fbclid','_openstat'].includes(lk))continue;
        pairs.push(encodeURIComponent(k)+'='+encodeURIComponent(v));
        if(params[k]===undefined)params[k]=v;
