}
function hostMatches(host,domain){return host===domain||host.endsWith('.'+domain);}
function paramGet(p,key){
  if(!p||!p.params)return'';
  if(p.params[key]!==undefined)return String(p.params[key]);
  const lk=String(key).toLowerCase();
  for(const k of Object.keys(p.params)){if(String(k).toLowerCase()===lk)return String(p.params[k]);}
  return'';
}
function atomicTenderIdentity(raw){
  const p=parseHttpUrl(raw);if(!p)return'';
  const h=p.host,path=p.path;
  let m=null;
  if(hostMatches(h,'zakupki.gov.ru')&&/\/epz\/order\/notice\//i.test(path)){
    const reg=paramGet(p,'regNumber'),ni=paramGet(p,'noticeInfoId');
    if(reg&&/^\d{6,}$/.test(reg))return'zakupki:reg:'+reg;
    if(ni&&/^\d+$/.test(ni))return'zakupki:notice:'+ni;
  }
  if(hostMatches(h,'rts-tender.ru')&&(m=path.match(/\/tender-(\d+)(?:\/|$)/i)))return'rts:'+m[1];
  if(hostMatches(h,'b2b-center.ru')&&(m=path.match(/\/tender-(\d+)(?:\/|$)/i)))return'b2b-center:'+m[1];
  if(hostMatches(h,'vsem-podryad.ru')&&(m=path.match(/\/(request|purchase|activepurchase)\/([0-9a-f-]{36})(?:\/|$)/i)))return'vsem-podryad:'+m[2].toLowerCase();
  if(hostMatches(h,'b2b.house')&&(m=path.match(/\/activepurchase\/([^/?#]+)(?:\/|$)/i)))return'b2b-house:'+m[1].toLowerCase();
  if(hostMatches(h,'initpro.ru')&&(m=path.match(/\/tender\/([^/?#]+)(?:\/|$)/i)))return'initpro:'+m[1].toLowerCase();
  if(hostMatches(h,'synapsenet.ru')&&(m=path.match(/\/zakupki\/([a-z0-9_-]+)\/([^/?#]*\d[^/?#]*)/i)))return'synapsenet:'+m[1].toLowerCase()+':'+m[2].toLowerCase();
  if(hostMatches(h,'tender.pro')){
    if((m=path.match(/\/api\/tender\/([^/?#]+)\/view_public(?:\/|$)/i)))return'tenderpro:api:'+m[1].toLowerCase();
    if(/\/view_tender_public\.shtml$/i.test(path)){const id=paramGet(p,'tenderid');if(id)return'tenderpro:public:'+id.toLowerCase();}
    if((m=path.match(/\/(?:tender|procurement|notice)\/([^/?#]+)(?:\/|$)/i)))return'tenderpro:direct:'+m[1].toLowerCase();
  }
  if(hostMatches(h,'tenderland.ru')&&(m=path.match(/\/(?:tender|procurement|notice)\/([^/?#]+)(?:\/|$)/i)))return'tenderland:'+m[1].toLowerCase();
  return'';
}
function obviousNonTenderOrListing(raw){
  const p=parseHttpUrl(raw);if(!p)return'INVALID';
  const h=p.host,path=p.path.toLowerCase();
  if(hostMatches(h,'zakupki.gov.ru')&&/\/epz\/contract\/contractcard\//i.test(path))return'NON_TENDER';
  if(/\/(?:search|catalog|catalogue|category|categories|archive|news|articles?|suppliers?|customers?)(?:\/|$)/i.test(path))return'LISTING';
